def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def best_by(items, score_fn, default=None):
        if not items:
            return default
        best_item = items[0]
        best_score = score_fn(best_item)
        for item in items[1:]:
            s = score_fn(item)
            if s < best_score:
                best_score = s
                best_item = item
        return best_item

    env = observation.get("environment_name", "resource_collection") if hasattr(observation, "get") else "resource_collection"

    self_pos = pos(observation.get("self_position") if hasattr(observation, "get") else None)
    opp_pos = pos(observation.get("opponent_position") if hasattr(observation, "get") else None, default=(self_pos[0], self_pos[1]))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") if hasattr(observation, "get") else "pursuer"
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0) if hasattr(observation, "get") else 0
        gh = observation.get("grid_height", 0) if hasattr(observation, "get") else 0
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if gw > 0 and gh > 0:
            target = best_by(corners, lambda c: -dist(c, opp_pos), corners[0])
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier", "targets"):
            cand = observation.get(key) if hasattr(observation, "get") else None
            if cand:
                targets = cand
                break
        if targets:
            target = best_by(targets, lambda c: dist(pos(c), self_pos))
            return step_toward(self_pos, pos(target))
        return step_away(self_pos, opp_pos)

    resources = []
    for key in ("resources", "resource_positions", "items", "points"):
        cand = observation.get(key) if hasattr(observation, "get") else None
        if cand:
            resources = cand
            break

    if resources:
        def resource_score(r):
            rp = pos(r)
            return dist(rp, self_pos) * 2 + max(0, 8 - dist(rp, opp_pos))
        target = best_by(resources, resource_score)
        return step_toward(self_pos, pos(target))

    # Fallback: avoid opponent, else stay put.
    if self_pos != opp_pos:
        return step_away(self_pos, opp_pos)
    return [0, 0]

